preConditionHook:
// EEC E35. CCI is fresh from prices every bar (EL_FEATURES `cci`, VERIFIED):
// (TP - SMA(TP, N)) / (0.015 * mean absolute deviation), TP = (H+L+C)/3, the
// window INCLUDING the current bar, each summation NEWEST-FIRST -- bar [0]
// added first, the EL Summation order. Braced so the scratch doubles stay
// scoped to this placement.
{
    double tpMean = 0.0;
    for (int i = 0; i < (int)cciLength; ++i) {
        tpMean += (high[i] + low[i] + close[i]) / 3;
    }
    tpMean /= (int)cciLength;
    double meanDev = 0.0;
    for (int i = 0; i < (int)cciLength; ++i) {
        meanDev += std::fabs((high[i] + low[i] + close[i]) / 3 - tpMean);
    }
    meanDev /= (int)cciLength;
    cciVal = ((high[0] + low[0] + close[0]) / 3 - tpMean) / (0.015 * meanDev);
}
// The book assigns the CCI to the VARIABLE CCIValue and averages THAT, so
// Average(CCIValue, avgLength) reads the variable's own zero-filled warm-up
// history -- mirrored here as a zero-initialised ring buffer of the CCI
// series, re-seeded if the length ever changes (BarRangeAboveStd is the
// reference pattern). Recomputing the average from prices instead would use
// bars EL never saw. The average itself also sums NEWEST-FIRST, EL's
// Summation order, hence the backwards walk from the newest slot.
if (cciHistory.size() != (std::size_t)(int)avgLength) {
    cciHistory.assign((std::size_t)(int)avgLength, 0.0);
    cciCursor = 0;
}
cciHistory[cciCursor] = cciVal;
cciCursor = (cciCursor + 1) % cciHistory.size();
cciAvg = 0.0;
for (std::size_t k = 0; k < cciHistory.size(); ++k) {
    cciAvg += cciHistory[(cciCursor + cciHistory.size() - 1 - k) % cciHistory.size()];
}
cciAvg /= (int)avgLength;
